import React, { useEffect, useState } from "react";

function Dashboard() {
  const [resumes, setResumes] = useState([]);

  useEffect(() => {
    fetchResumes();
  }, []);

  const fetchResumes = async () => {
    try {
      const token = localStorage.getItem("token");

      const res = await fetch("http://localhost:5000/api/resume/my", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      const data = await res.json();
      setResumes(data);

    } catch (err) {
      console.error(err);
    }
  };

  const handleDelete = async (id) => {
    try {
      const token = localStorage.getItem("token");

      await fetch(`http://localhost:5000/api/resume/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      // refresh list
      fetchResumes();

    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div style={styles.container}>
      <h2>Your Saved Resumes</h2>

      <div style={styles.topButtons}>
        <button
          style={styles.primaryBtn}
          onClick={() => (window.location.href = "/")}
        >
          Analyze Resume
        </button>

        <button
          style={styles.logoutBtn}
          onClick={() => {
            localStorage.removeItem("token");
            window.location.href = "/login";
          }}
        >
          Logout
        </button>
      </div>

      {resumes.length === 0 ? (
        <p>No resumes found</p>
      ) : (
        resumes.map((item) => (
          <div key={item._id} style={styles.card}>
            
            <h3>ATS Score: {item.atsScore}</h3>

            <p style={styles.text}>
              {item.resume}
            </p>

            <button
              style={styles.deleteBtn}
              onClick={() => handleDelete(item._id)}
            >
              Delete
            </button>

          </div>
        ))
      )}
    </div>
  );
}

const styles = {
  container: {
    padding: "20px",
    color: "white",
  },
  topButtons: {
    display: "flex",
    justifyContent: "flex-end",
    gap: "10px",
    marginBottom: "20px",
  },
  primaryBtn: {
    background: "#007bff",
    color: "white",
    border: "none",
    padding: "10px 15px",
    cursor: "pointer",
  },
  logoutBtn: {
    background: "red",
    color: "white",
    border: "none",
    padding: "10px 15px",
    cursor: "pointer",
  },
  card: {
    background: "#111",
    padding: "15px",
    borderRadius: "8px",
    marginBottom: "15px",
  },
  text: {
    whiteSpace: "pre-wrap",
    marginTop: "10px",
  },
  deleteBtn: {
    marginTop: "10px",
    background: "orange",
    border: "none",
    padding: "10px",
    width: "100%",
    cursor: "pointer",
  },
};

export default Dashboard;
